const $=s=>document.querySelector(s);$("#displayStatus").textContent=PREMIERE_API.configured?"REALTIME CONNECTED":"DEMO CHANNEL";
PREMIERE_API.subscribe(e=>{const id=e.ticket_id||e.ticketId,local=PREMIERE.tickets.find(t=>t.ticketId===id),t={...local,...e},teacher=t.type==="teacher"||t.ticket_type==="teacher";$("#displayIdle").hidden=true;$("#displayGuest").hidden=false;$("#displayGuest").className=`display-guest is-entering ${teacher?"teacher":""}`;$("#displayKicker").textContent=teacher?"SPECIAL ACCESS DETECTED":"ACCESS GRANTED";$("#displayName").textContent=t.name||t.guest_name||"WELCOME";$("#displayMeta").textContent=`${teacher?"HONORED GUEST":t.role||t.ticket_role||"GUEST"} · № ${t.number||t.ticket_number||"—"}`;$("#displaySecret").hidden=!teacher;clearTimeout(window.displayTimer);window.displayTimer=setTimeout(()=>{$("#displayGuest").hidden=true;$("#displayIdle").hidden=false},12000)});
